import base64
from PIL import Image
import io

# ضع نص الـ Base64 هنا
base64_string = ""


image_data = base64.b64decode(base64_string)
image = Image.open(io.BytesIO(image_data))

# عرض الصورة فوراً
image.show()

# أو حفظها كملف
image.save("result_overlay.png")
print("تم حفظ الصورة بنجاح باسم result_overlay.png")